// Normalise an inbound support email into the Django /api/n8n/incoming-email/ shape
// and compute the X-Signature over the EXACT JSON string we will POST.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET;
if (!secret) { throw new Error('N8N_SHARED_SECRET is not set'); }

const out = [];
for (const item of $input.all()) {
  const m = item.json || {};
  // Gmail node field names vary slightly by version; cover common shapes.
  const headers = m.headers || {};
  const fromRaw = m.from || m.From || headers.from || (m.payload && m.payload.from) || '';
  const fromMatch = /<([^>]+)>/.exec(fromRaw);
  const fromEmail = (fromMatch ? fromMatch[1] : fromRaw).trim();
  const subject = m.subject || m.Subject || headers.subject || '';
  const bodyText = m.text || m.textPlain || m.snippet || '';
  const bodyHtml = m.html || m.textHtml || '';
  const messageId = m.id || m.messageId || headers['message-id'] || '';
  const threadId = m.threadId || m.thread_id || '';

  // Best-effort language hint from the subject/body (default en).
  const blob = (subject + ' ' + bodyText).toLowerCase();
  let language = 'en';
  if (/\b(merci|bonjour|commande|remboursement)\b/.test(blob)) language = 'fr';
  else if (/\b(grazie|ciao|ordine|rimborso)\b/.test(blob)) language = 'it';

  const payload = {
    from_email: fromEmail,
    to_email: m.to || $env.SUPPORT_EMAIL || '',
    subject,
    body_text: bodyText,
    body_html: bodyHtml,
    message_id: messageId,
    thread_id: threadId,
    language,
    attachments: [],
    auto_reply: true
  };

  // IMPORTANT: sign the EXACT serialized string we send as the HTTP body.
  const bodyString = JSON.stringify(payload);
  const signature = crypto.createHmac('sha256', secret).update(bodyString, 'utf8').digest('hex');

  out.push({ json: { bodyString, signature } });
}
return out;
